import { fileURLToPath } from "node:url";
import { migrate } from "drizzle-orm/libsql/migrator";
import { env } from "../env";
import { client, db } from "./index";

/** SQL migrations generated by `drizzle-kit generate` (committed). */
export const migrationsFolder = fileURLToPath(new URL("./migrations", import.meta.url));

let pending: Promise<void> | null = null;

/** Apply pending migrations. Safe to call more than once. */
export function runMigrations(): Promise<void> {
	pending ??= (async () => {
		if (env.databaseUrl.startsWith("file:") && !env.databaseUrl.includes(":memory:")) {
			// WAL lets readers proceed while a sync batch is being written.
			await client.execute("PRAGMA journal_mode = WAL");
		}
		await migrate(db, { migrationsFolder });
	})();
	return pending;
}
